// Filter function for search input
window.onSearchInput = function(q) {
    const providerCards = document.querySelectorAll('#provider-list .card');
    providerCards.forEach(card => {
        const name = card.querySelector('.card-title').innerText.toLowerCase();
        card.style.display = name.includes(q.toLowerCase()) ? 'block' : 'none';
    });
};

